    const jump = active && ["happy", "excited", "startle"].includes(this.reaction) ? Math.sin(phase * Math.PI) * (this.reaction === "startle" ? h * .008 : h * .003) : 0;
    ctx.translate(w * .5, h * .96 - jump); ctx.rotate(sway); ctx.scale(1, 1 + breath * .0008); ctx.translate(-w * .5, -h * .96);
