      // and reveals a row of keys as each wrist lifts away from the laptop.
      ctx.save(); const holes = new Path2D();
      this.cfg.hands.forEach(hand => holes.addPath(polygon(hand.path)));
      ctx.clip(holes); const [sx, sy] = this.cfg.screen.origin;
      ctx.fillStyle = "#eddec6"; ctx.fillRect(sx - 220, sy - 73, 440, 80);
      ctx.fillStyle = "#37332e"; ctx.fillRect(sx - 56, sy - 73, 112, 80);
      // Under each lifting hand: its own soft shadow (the resting hand, faded and darkened), not a grey key strip —
      // the strip showed as a hard slice across the fingertips and made the hands look cut off.
