      ctx.fillStyle = curious ? "#efd28e" : "#e5a38d"; ctx.beginPath(); ctx.ellipse(0, 0, r * .43, r * .5, -.08, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = "#69503d"; ctx.fillText(curious ? "?" : "!", 0, r * .025);
